UPDATE signatories SET name='HR Team', designation='People Operations', is_active=1 WHERE id='sig_hr';
UPDATE signatories SET is_active=0 WHERE id='sig_founder';

UPDATE templates SET signatory_ids_json='["sig_hr"]', default_opening_html='<p>Dear {{recipient_name}},</p><p>We are pleased to offer you the position of <strong>{{designation}}</strong> at Labdox. Your skills, enthusiasm, and potential stood out during our selection process, and we believe you will make a valuable contribution to the team.</p><p>Your role will involve working closely with your assigned team, taking ownership of agreed responsibilities, and following Labdox policies and professional standards. The detailed terms of your engagement, including your joining date, work arrangement, and applicable benefits, will be communicated separately.</p>', default_closing_html='<p>Please confirm your acceptance by signing and returning a copy of this letter. We look forward to welcoming you to Labdox and supporting your professional growth.</p><p>Warm regards,</p>', updated_at=CURRENT_TIMESTAMP WHERE id='tpl_offer';
UPDATE templates SET signatory_ids_json='["sig_hr"]', default_opening_html='<p>To whom it may concern,</p><p>We are pleased to recommend <strong>{{recipient_name}}</strong>, who worked with Labdox as <strong>{{designation}}</strong>. During this association, they consistently demonstrated professionalism, responsibility, and a willingness to learn.</p><p>They approached assigned work with care, communicated effectively with colleagues, and responded positively to feedback. Their ability to understand requirements and complete responsibilities within expected timelines made them a dependable member of the team.</p>', default_closing_html='<p>Based on their performance and conduct, we are confident that {{recipient_name}} will be a valuable addition to future academic or professional opportunities. We recommend them without reservation and wish them continued success.</p><p>Sincerely,</p>', updated_at=CURRENT_TIMESTAMP WHERE id='tpl_lor';
UPDATE templates SET signatory_ids_json='["sig_hr"]', default_opening_html='<p>Dear {{recipient_name}},</p><p>Welcome to Labdox. This letter confirms your joining as <strong>{{designation}}</strong> with effect from the date agreed with the HR Team.</p><p>As part of your onboarding, you will receive information about your reporting structure, responsibilities, internal policies, and the resources required for your role. Please complete the requested documentation and induction formalities within the communicated timelines.</p>', default_closing_html='<p>We are delighted to have you join us and hope your journey at Labdox will be engaging, productive, and rewarding. Please contact the HR Team if you need any assistance during onboarding.</p><p>Warm regards,</p>', updated_at=CURRENT_TIMESTAMP WHERE id='tpl_joining';
UPDATE templates SET signatory_ids_json='["sig_hr"]', default_opening_html='<p>Dear {{recipient_name}},</p><p>We are delighted to confirm your appointment as <strong>{{designation}}</strong> at Labdox. This appointment reflects our confidence in your ability to contribute effectively to the organisation.</p><p>You will perform the responsibilities assigned to your role, maintain professional conduct, protect confidential information, and comply with applicable company policies. Your detailed terms of appointment and any role-specific conditions form part of the accompanying employment documentation.</p>', default_closing_html='<p>Please acknowledge your acceptance by signing and returning a copy of this letter. We look forward to a positive and mutually rewarding association.</p><p>Warm regards,</p>', updated_at=CURRENT_TIMESTAMP WHERE id='tpl_appointment';
UPDATE templates SET signatory_ids_json='["sig_hr"]', default_opening_html='<p>Dear {{recipient_name}},</p><p>We are writing to formally communicate the following information for your reference and necessary action.</p>', default_closing_html='<p>Please contact the HR Team if you require any clarification or supporting information. We appreciate your attention to this matter.</p><p>Warm regards,</p>', updated_at=CURRENT_TIMESTAMP WHERE id='tpl_generic';
